package net.battlespades.bot;
import java.util.*;
import net.battlespades.physics.PlayerPhysics.Vector;
import static net.battlespades.bot.BotState.*;
/** Source body-wide walking lookahead, exact-edge alignment and stable travel gaze. */
public final class PathFollowing {
    public static final double SAFE_DROP=4.;private PathFollowing(){}
    private static boolean running(Affordance a){return a==Affordance.WALK||a==Affordance.DROP;}
    private static double distance(Vector a,Vector b){return Math.hypot(a.x()-b.x(),a.y()-b.y());}
    public static int runEnd(List<RouteStep> route,int index){if(index>=route.size()||!running(route.get(index).affordance()))return index;int end=index;for(int following=index+1;following<Math.min(route.size(),index+17);following++){var step=route.get(following);var before=route.get(following-1);double stride=distance(step.waypoint(),before.waypoint()),change=step.waypoint().z()-before.waypoint().z();if(!running(step.affordance())||-change>Math.max(1,stride)*1.05||change>Math.max(SAFE_DROP,stride*1.05))break;end=following;}return end;}
    public static Vector edgeAxis(RouteStep step){var e=step.entryEdge();if(e==null)return null;int x=Integer.compare(e.target().x(),e.source().x()),y=Integer.compare(e.target().y(),e.source().y());return (x==0)==(y==0)?null:new Vector(x,y,0);}
    public static Vector takeoffAlignment(RouteStep step,Vector at){var e=step.entryEdge();var axis=edgeAxis(step);if(axis==null)return null;double ox=at.x()-(e.source().x()+.5),oy=at.y()-(e.source().y()+.5),along=ox*axis.x()+oy*axis.y(),lateral=-ox*axis.y()+oy*axis.x();if(Math.abs(lateral)<=.3||along>.45||Math.abs(lateral)>2.5)return null;double back=Math.min(along,.1);return new Vector(e.source().x()+.5+axis.x()*back,e.source().y()+.5+axis.y()*back,at.z());}
    public static boolean straightWalkable(BotNavigationWorld world,Vector origin,Vector target){return straightWalkable(world,origin,target,.42);}
    public static boolean straightWalkable(BotNavigationWorld world,Vector origin,Vector target,double halfWidth){double dx=target.x()-origin.x(),dy=target.y()-origin.y(),length=Math.hypot(dx,dy);if(length<1e-6)return true;if(!Double.isFinite(length))throw new IllegalArgumentException("Nonfinite walking segment");if(length>2048)return false;double ux=dx/length,uy=dy/length,sx=-uy*halfWidth,sy=ux*halfWidth,height=origin.z();int behindX=(int)Math.floor(origin.x()),behindY=(int)Math.floor(origin.y()),samples=Math.max(1,(int)Math.ceil(length/.5));for(int n=1;n<=samples;n++){double travel=Math.min(length,n*.5),x=origin.x()+ux*travel,y=origin.y()+uy*travel;Double center=null;for(double[] offset:new double[][]{{0,0},{sx,sy},{-sx,-sy}}){Double ground=ground(world,x+offset[0],y+offset[1],height);if(ground==null)return false;if(center==null)center=ground;}double lifted=lifted(world,x,y,center);int hereX=(int)Math.floor(x),hereY=(int)Math.floor(y);if(lifted<height-.5){int head=(int)Math.rint(lifted+2.25)-3;if(world.solid(behindX,behindY,head)||world.solid(hereX,hereY,head))return false;}height=lifted;behindX=hereX;behindY=hereY;}return Math.abs(height-target.z())<=1.05;}
    private static double lifted(BotNavigationWorld world,double x,double y,double height){int feet=(int)Math.rint(height+2.25);var seen=new HashSet<Cell>();seen.add(new Cell((int)Math.floor(x),(int)Math.floor(y),0));for(double ox:new double[]{-.45,.45})for(double oy:new double[]{-.45,.45}){int cx=(int)Math.floor(x+ox),cy=(int)Math.floor(y+oy);if(!seen.add(new Cell(cx,cy,0)))continue;if(world.solid(cx,cy,feet-1)&&!world.solid(cx,cy,feet-2)&&!world.solid(cx,cy,feet-3)&&!world.solid(cx,cy,feet-4))return height-1;}return height;}
    private static Double ground(BotNavigationWorld world,double x,double y,double height){int cx=(int)Math.floor(x),cy=(int)Math.floor(y),feet=(int)Math.rint(height+2.25);var level=world.surface(cx,cy,height,1,false);if(level!=null&&Math.abs(level.position().z()-height)<=1.05){int top=Math.min(feet,level.supportZ())-3;for(int z=top;z<level.supportZ();z++)if(world.solid(cx,cy,z))return null;return level.position().z();}for(int z=feet-3;z<feet;z++)if(world.solid(cx,cy,z))return null;for(int support=feet;support<=feet+(int)SAFE_DROP;support++)if(world.solid(cx,cy,support)){var landing=world.surface(cx,cy,support-2.25,0,false);return landing==null?null:landing.position().z();}return null;}
    public static boolean runsOff(BotNavigationWorld world,RouteStep step,Vector at){return step.affordance()==Affordance.DROP&&step.waypoint().z()-at.z()<=SAFE_DROP+.05&&straightWalkable(world,at,step.waypoint(),.25);}
    private static boolean same(Vector a,Vector b){return a.x()==b.x()&&a.y()==b.y()&&a.z()==b.z();}
    public static int lookahead(BotNavigationWorld world,List<RouteStep> route,int index,Vector position,Vector keep){int end=runEnd(route,index);if(end<=index)return index;if(keep!=null)for(int candidate=index+1;candidate<=end;candidate++)if(same(route.get(candidate).waypoint(),keep)){double gap=distance(keep,position);if((gap>=6.5||candidate==end)&&straightWalkable(world,position,keep))return candidate;break;}for(int offset:new int[]{16,11,7,4,2,1}){int candidate=Math.min(end,index+offset);if(candidate<=index)continue;var point=route.get(candidate).waypoint();double gap=distance(point,position);if(gap>12)continue;if(straightWalkable(world,position,point,gap>3.5?.42:.25))return candidate;}return index;}
    public static int heldIndex(List<RouteStep> route,int index,Vector keep){if(keep!=null)for(int candidate=index+1;candidate<=runEnd(route,index);candidate++)if(same(route.get(candidate).waypoint(),keep))return candidate;return index;}
    public static int passedIndex(List<RouteStep> route,int index,int targetIndex,Vector position){var target=route.get(targetIndex).waypoint();double hx=target.x()-position.x(),hy=target.y()-position.y();while(index<targetIndex){var point=route.get(index).waypoint();double ahead=(point.x()-position.x())*hx+(point.y()-position.y())*hy;if(ahead>0&&distance(point,position)>.9)break;index++;}return index;}
    public static Vector gazeWaypoint(List<RouteStep> route,int index,Vector position){double traveled=0;Vector previous=position,chosen=null;for(int i=index;i<Math.min(route.size(),index+32);i++){chosen=route.get(i).waypoint();traveled+=distance(chosen,previous);previous=chosen;if(traveled>=10)break;}return chosen==null||distance(chosen,position)<3?null:chosen;}
    public static double remainingDistance(List<RouteStep> route,int index,Vector position){double total=0;Vector previous=position;for(int i=index;i<route.size();i++){var point=route.get(i).waypoint();total+=distance(point,previous);previous=point;}return total;}
}
